  }
}

query getJoinedRooms($user_uuid: uuid!) {
  user_room(where: {user_uuid: {_eq: $user_uuid}}) {
    room {
      uuid
      name
      intro
      invite_code
      created_at
    }
  }
}

query getRoomByInviteCode($invite_code: String!) {
